<script setup>
import {formatPrice,resolveImage,CONDITION_LABELS,timeAgo} from '../utils/format';defineProps({item:{type:Object,required:true}});
</script>
<template><RouterLink :to="{name:'itemDetail',params:{id:item.id}}" class="item-card"><div class="product-image"><img :src="resolveImage(item.cover)" :alt="item.title" loading="lazy"/><span class="condition-label">{{CONDITION_LABELS[item.condition]||'好物闲置'}}</span><span v-if="item.status&&item.status!=='on_sale'" class="item-state">{{item.status==='sold'?'已售出':item.status==='reserved'?'已预定':'已下架'}}</span><span class="product-peek">看看这件好物</span></div><div class="product-copy"><span class="product-category">{{item.categoryName||'校园好物'}}</span><h3>{{item.title}}</h3><p v-if="item.bookCourse||item.bookEdition" class="book-card-meta">{{[item.bookCourse,item.bookEdition].filter(Boolean).join(' · ')}}</p><div class="product-price"><strong>{{formatPrice(item.price)}}</strong><del v-if="item.originalPrice">{{formatPrice(item.originalPrice)}}</del></div><div class="product-seller"><span><i>{{item.sellerNickname?.[0]||'同'}}</i>{{item.sellerNickname||'同学'}}</span><time>{{timeAgo(item.createdAt)}}</time></div></div></RouterLink></template>